import { getPageRSSHub, getWebsiteRSSHub } from "~/lib/rsshub"
import { parseRules } from "~/lib/rules"
import { removeFunctionFields } from "~/lib/utils"

export {}

export const getRSSHub = ({
  html,
  url,
  rules,
}: {
  html: string
  url: string
  rules: string
}) => {
  const pageRSSHub = getPageRSSHub({
    html,
    url,
    rules,
  })
  const websiteRSSHub = getWebsiteRSSHub({
    url,
    rules,
  })
  return {
    pageRSSHub,
    websiteRSSHub,
  }
}

export const getDisplayedRules = (rules: string) => {
  const displayedRules = parseRules(rules)
  removeFunctionFields(displayedRules)
  return displayedRules
}

if (typeof window !== "undefined") {
  window.addEventListener(
    "message",
    (
      event: MessageEvent<
        | {
            name: "requestRSSHub"
            body: {
              html: string
              url: string
              rules: string
              tabId: number
            }
          }
        | {
            name: "requestDisplayedRules"
            body: {
              rules: string
            }
          }
      >,
    ) => {
      switch (event.data?.name) {
        case "requestRSSHub": {
          const rsshub = getRSSHub({
            html: event.data.body.html,
            url: event.data.body.url,
            rules: event.data.body.rules,
          })
          event.source.postMessage(
            {
              name: "responseRSS",
              body: {
                url: "url" in event.data.body && event.data.body.url,
                tabId: "tabId" in event.data.body && event.data.body.tabId,
                rss: rsshub,
              },
            },
            event.origin as any,
          )
          break
        }
        case "requestDisplayedRules": {
          const displayedRules = getDisplayedRules(event.data.body.rules)
          event.source.postMessage(
            {
              name: "responseDisplayedRules",
              body: {
                displayedRules,
              },
            },
            event.origin as any,
          )
          break
        }
      }
    },
  )
}

import contentReady from "./messages/contentReady"
import offscreenReady from "./messages/offscreenReady"
import popupReady from "./messages/popupReady"
import refreshRules from "./messages/refreshRules"
import requestDisplayedRules from "./messages/requestDisplayedRules"
import responseDisplayedRules from "./messages/responseDisplayedRules"
import responseRSS from "./messages/responseRSS"
import { deleteCachedRSS, getRSS } from "./rss"
import { initSchedule } from "./rules"
import { initUpdateNotifications } from "./update-notifications"

export {}

chrome.tabs.onActivated.addListener((tab) => {
  chrome.tabs.get(tab.tabId, (info) => {
    if (info.url) {
      getRSS(tab.tabId, info.url)
    }
  })
})

chrome.tabs.onUpdated.addListener((tabId, changeInfo, tab) => {
  if (tab.active) {
    if (changeInfo.url) {
      deleteCachedRSS(tabId)
      getRSS(tabId, changeInfo.url)
    } else if (changeInfo.status === "loading") {
      deleteCachedRSS(tabId)
    } else if (changeInfo.status === "complete") {
      getRSS(tabId, tab.url)
    }
  }
})

chrome.tabs.onRemoved.addListener((tabId) => {
  deleteCachedRSS(tabId)
})

chrome.runtime.onMessage.addListener((msg, sender, sendResponse) => {
  const run = async () => {
    switch (msg?.name) {
      case "contentReady":
        return contentReady(msg, sender)
      case "offscreenReady":
        return offscreenReady()
      case "popupReady":
        return popupReady(msg, sender)
      case "refreshRules":
        return refreshRules(msg, sender)
      case "requestDisplayedRules":
        return requestDisplayedRules(msg, sender)
      case "responseDisplayedRules":
        return responseDisplayedRules(msg, sender)
      case "responseRSS":
        return responseRSS(msg, sender)
      default:
        return undefined
    }
  }

  run()
    .then((res) => {
      sendResponse(res)
    })
    .catch((error) => {
      console.error(error)
      sendResponse(undefined)
    })

  return true
})

initSchedule()
initUpdateNotifications()

