import { afterEach, beforeEach, describe, expect, it, vi } from "vitest"

import { getPageRSS } from "./rss"

const FEED = `<?xml version="1.0"?><rss version="2.0"><channel><title>Example feed</title></channel></rss>`

const fetchSpy = vi.fn(async (_input: RequestInfo | URL) => new Response(FEED))

function requestedPaths() {
  return fetchSpy.mock.calls.map(([input]) => new URL(String(input)).pathname)
}

beforeEach(() => {
  history.replaceState(null, "", "/login")
  document.head.innerHTML = "<title>Sign in</title>"
  document.body.innerHTML = ""
  fetchSpy.mockClear()
  vi.stubGlobal("fetch", fetchSpy)
})

afterEach(() => {
  vi.unstubAllGlobals()
})

describe("getPageRSS", () => {
  it("never requests the current page through links that point back to it", async () => {
    document.body.innerHTML = `
      <form method="post"><input type="hidden" name="csrf" value="token"></form>
      <a href="#" class="rss-icon">RSS</a>
      <a href="" title="RSS">Subscribe</a>
      <a href="#comments">Feed</a>
    `

    const { pageRSS } = await getPageRSS()

    expect(requestedPaths()).not.toContain("/login")
    expect(pageRSS).toEqual([])
  })

  it("still checks links that look like feeds", async () => {
    document.body.innerHTML = `<a href="/feed">RSS</a>`

    const { pageRSS } = await getPageRSS()

    expect(requestedPaths()).toEqual(["/feed"])
    expect(pageRSS).toMatchObject([
      { url: `${location.origin}/feed`, title: "Example feed" },
    ])
  })

  it("detects feeds declared in the head without requesting them", async () => {
    document.head.innerHTML += `<link rel="alternate" type="application/rss+xml" title="Posts" href="/posts.xml">`

    const { pageRSS } = await getPageRSS()

    expect(fetchSpy).not.toHaveBeenCalled()
    expect(pageRSS).toMatchObject([
      { url: `${location.origin}/posts.xml`, title: "Posts" },
    ])
  })

  it("detects a feed shown as plain text from the DOM without requesting it", async () => {
    const pre = document.createElement("pre")
    pre.textContent = FEED
    document.body.append(pre)

    const { pageRSS } = await getPageRSS()

    expect(fetchSpy).not.toHaveBeenCalled()
    expect(pageRSS).toMatchObject([
      { url: location.href, title: "Example feed" },
    ])
  })
})

const LEGACY_STORAGE_KEYS = [
  "config",
  "rules",
  "displayedRules",
  "version",
] as const

let legacyStorageMigration: Promise<void> | undefined

/**
 * v2.2.0 moved the extension from Plasmo to WXT. Plasmo stored data in
 * `chrome.storage.sync` as JSON strings, while the new implementation uses
 * `chrome.storage.local` with plain values. Copy the old data over once so
 * existing users keep their settings after upgrading.
 */
export function migrateLegacyStorage() {
  if (!legacyStorageMigration) {
    legacyStorageMigration = migrateLegacyStorageInternal().catch((error) => {
      console.error("Failed to migrate legacy storage", error)
    })
  }
  return legacyStorageMigration
}

async function migrateLegacyStorageInternal() {
  const local = await chrome.storage.local.get(["legacyStorageMigrated"])
  if (local.legacyStorageMigrated) {
    return
  }

  let sync: Record<string, unknown> = {}
  try {
    sync = await chrome.storage.sync.get([...LEGACY_STORAGE_KEYS])
  } catch (error) {
    // Firefox may reject access to the sync area when it is unavailable.
    console.error("Failed to read legacy storage", error)
  }

  const localValues = await chrome.storage.local.get([...LEGACY_STORAGE_KEYS])
  const migrated: Record<string, unknown> = {}

  for (const key of LEGACY_STORAGE_KEYS) {
    if (localValues[key] !== undefined || sync[key] === undefined) {
      continue
    }

    const value = sync[key]
    if (typeof value === "string") {
      try {
        migrated[key] = JSON.parse(value)
      } catch {
        migrated[key] = value
      }
    } else {
      migrated[key] = value
    }
  }

  if (Object.keys(migrated).length > 0) {
    await chrome.storage.local.set(migrated)
  }
  await chrome.storage.local.set({ legacyStorageMigrated: true })
}

export async function getLocalStorage<T = any>(key: string) {
  await migrateLegacyStorage()
  return new Promise<T>((resolve, reject) => {
    chrome.storage.local.get(key, (result) => {
      if (chrome.runtime.lastError) {
        reject(new Error(chrome.runtime.lastError.message))
        return
      }

      resolve(result[key] as T)
    })
  })
}

export async function setLocalStorage<T = any>(key: string, value: T) {
  await migrateLegacyStorage()
  return new Promise<void>((resolve, reject) => {
    chrome.storage.local.set(
      {
        [key]: value,
      },
      () => {
        if (chrome.runtime.lastError) {
          reject(new Error(chrome.runtime.lastError.message))
          return
        }

        resolve()
      },
    )
  })
}

import { describe, expect, it } from "vitest"

import { isLikelyFeedUrl, isSameDocumentUrl } from "./utils"

describe("isLikelyFeedUrl", () => {
  it.each([
    "https://example.com/feed",
    "https://example.com/feed/",
    "https://example.com/blog/rss.xml",
    "https://example.com/atom.xml",
    "https://example.com/index.rss",
    "https://example.com/feeds/posts/default",
    "https://example.com/?feed=rss2",
    "https://example.com/news?format=atom",
  ])("matches %s", (url) => {
    expect(isLikelyFeedUrl(url)).toBe(true)
  })

  it.each([
    "https://sep.ucas.ac.cn/",
    "https://example.com/login",
    "https://example.com/login?redirect=/feed",
    "https://example.com/account/sign-in?next=%2Fhome",
    "https://example.com/rssreader-review",
    "ftp://example.com/feed.xml",
    "not a url",
  ])("does not match %s", (url) => {
    expect(isLikelyFeedUrl(url)).toBe(false)
  })
})

describe("isSameDocumentUrl", () => {
  it("ignores the hash and the protocol", () => {
    expect(
      isSameDocumentUrl(
        "https://example.com/login?next=1#",
        "http://example.com/login?next=1",
      ),
    ).toBe(true)
  })

  it("distinguishes other paths and queries", () => {
    expect(
      isSameDocumentUrl(
        "https://example.com/feed",
        "https://example.com/login",
      ),
    ).toBe(false)
    expect(
      isSameDocumentUrl(
        "https://example.com/login?a=1",
        "https://example.com/login?a=2",
      ),
    ).toBe(false)
  })
})

import "~/lib/style.css"

import { useEffect, useState } from "react"

import { useDark } from "~/lib/hooks/use-dark"
import { sendToBackground } from "~/lib/messaging"
import report from "~/lib/report"

import RSSList from "./RSSList"

function IndexPopup() {
  useDark()

  const [data, setData] = useState({
    pageRSS: [],
    pageRSSHub: [],
    websiteRSSHub: [],
  })
  useEffect(() => {
    sendToBackground({
      name: "popupReady",
    }).then((res) => {
      setData(
        Object.assign(
          {
            pageRSS: [],
            pageRSSHub: [],
            websiteRSSHub: [],
          },
          res,
        ),
      )
    })

    chrome.tabs.query(
      {
        active: true,
      },
      ([tab]) => {
        report({
          url: tab.url,
          name: "popup",
        })
      },
    )
  }, [])

  return (
    <div className="min-w-[350px] p-5">
      <a
        className="absolute right-4 h-6 flex items-center"
        href="/options.html"
        target="_blank"
      >
        <i className="i-mingcute-settings-3-line w-5 h-5 text-slate-600 dark:text-slate-400 hover:text-black dark:hover:text-white transition-colors"></i>
      </a>
      {!data.pageRSS.length &&
        !data.pageRSSHub.length &&
        !data.websiteRSSHub.length && (
          <div className="space-y-4">
            <h2 className="text-base font-bold">
              ( ´･･)ﾉ(._.`) <span>{chrome.i18n.getMessage("RSSNotFound")}</span>
            </h2>
            <p
              dangerouslySetInnerHTML={{
                __html: chrome.i18n.getMessage("joinRSSHub"),
              }}
            ></p>
          </div>
        )}
      <RSSList type="currentPageRSS" list={data.pageRSS} />
      <RSSList type="currentPageRSSHub" list={data.pageRSSHub} />
      <RSSList type="currentSiteRSSHub" list={data.websiteRSSHub} />
    </div>
  )
}

export default IndexPopup

